+use packet::{
+    dev::{DevInst, DevInst64, TENSOR_NONE, TENSOR_NONE16},
+    devbuild::{Model, Program, SectionData, TensorDecl},
+};
+use plowrt::asset::devblob::{DevBlob, DevProg};
+use std::path::Path;
+fn unpack(i: &DevInst64) -> DevInst {
+    DevInst {
+        op: i.op,
+        blocks: i.blocks,
+        wait_len: 0,
+        succ_len: 0,
+        wait_ofs: 0,
+        succ_ofs: 0,
+        t: i.t.map(|h| {
+            if h == TENSOR_NONE16 {
+                TENSOR_NONE
+            } else {
+                h as u32
+            }
+        }),
+        i: i.i,
+        f: [f32::from_bits(i.fj[0]), 0.],
+        j: [i.fj[1], i.fj[2]],
+    }
+}
+fn program(g: &DevProg, n_cu: u32, t: &[TensorDecl]) -> Program {
+    Program {
+        n_cu,
+        n_counter: g.n_counter,
+        hier_base: 0,
+        insts: g.insts.iter().map(unpack).collect(),
+        stream: g.stream.clone(),
+        stream_ofs: g.stream_ofs.clone(),
+        stream_len: g.stream_len.clone(),
+        waits: g.waits.clone(),
+        succs: g.succs.clone(),
+        tensors: t.to_vec(),
+        gq_stream: g.gq_stream.clone(),
+        gq_seg_ofs: g.gq_seg_ofs.clone(),
+        l2_sms: 0,
+        l2_domains: 0,
+    }
+}
+fn main() -> Result<(), Box<dyn std::error::Error>> {
+    let args: Vec<_> = std::env::args().collect();
+    if args.len() != 4 {
+        return Err("usage: decode_object_fixture input.pkt output.pkt bindings.json|null".into());
+    }
+    let raw = std::fs::read(&args[1])?;
+    let metadata: Option<plow_asset::decode_objects::DecodeObjects> =
+        serde_json::from_slice(&std::fs::read(&args[3])?)?;
+    let Some(metadata) = metadata else {
+        std::fs::write(&args[2], &raw)?;
+        println!("PASS disabled binding is byte-identical");
+        return Ok(());
+    };
+    let blob = DevBlob::parse(&raw)?;
+    let start = blob.prefill_progs().len();
+    metadata.validate(
+        &blob
+            .progs
