+    )?;
+    assert!(blob.tp.is_none());
+    for g in blob.decode_progs() {
+        g.check_coarse_single_segment()?;
+        g.check_gq_topological()?;
+    }
+    for object in metadata.objects.values() {
+        let image = std::fs::read(
+            Path::new(&args[2])
+                .parent()
+                .ok_or("output directory required")?
+                .join(&object.file),
+        )?;
+        assert!(object.matches_image(&image), "object content mismatch");
+        let info = plowrt::asset::cubin::inspect(&image).ok_or("invalid object ELF")?;
+        assert_eq!(info.sm, 90);
+        assert!(info.entries.contains(&object.entry));
+    }
+    let tensors: Vec<_> = blob
+        .tensors
+        .iter()
+        .map(|t| TensorDecl {
+            name: t.name.clone(),
+            bytes: t.bytes,
+            init: t.init.clone().map(|v| blob.init[v].to_vec()),
+        })
+        .collect();
+    let model = Model {
+        n_cu: blob.n_cu,
+        target: blob.target,
+        tensors: tensors.clone(),
+        progs: blob
+            .progs
+            .iter()
+            .map(|g| program(g, blob.n_cu, &tensors))
+            .collect(),
+        kv_row_insts: blob.kvrow.clone(),
+        prog_t: blob.progs.iter().map(|g| g.t).collect(),
+        gen: blob.gen.clone(),
+    };
+    assert!(!blob
+        .sections
+        .iter()
+        .any(|s| s.kind == packet::devbuild::SECT_METADATA
+            && s.name == plow_asset::decode_objects::SECTION));
+    let mut sections: Vec<_> = blob
+        .sections
+        .iter()
+        .filter(|s| s.kind != packet::devbuild::SECT_GEN_TENSORS)
+        .map(|s| SectionData {
+            kind: s.kind,
+            name: s.name.clone(),
+            data: raw[s.offset..s.offset + s.size].to_vec(),
+        })
+        .collect();
+    sections.push(SectionData {
+        kind: packet::devbuild::SECT_METADATA,
+        name: plow_asset::decode_objects::SECTION.into(),
+        data: serde_json::to_vec(&metadata)?,
+    });
+    let output = model.to_blob_v6(&sections);
+    let after = DevBlob::parse(&output)?;
+    assert_eq!(blob.n_cu, after.n_cu);
+    assert_eq!(blob.kvrow, after.kvrow);
+    assert_eq!(blob.gen, after.gen);
+    for (a, b) in blob.progs.iter().zip(&after.progs) {
+        assert_eq!(a.t, b.t);
+        assert_eq!(a.insts, b.insts);
+        assert_eq!(a.stream, b.stream);
+        assert_eq!(a.stream_ofs, b.stream_ofs);
+        assert_eq!(a.stream_len, b.stream_len);
+        assert_eq!(a.waits, b.waits);
+        assert_eq!(a.succs, b.succs);
+        assert_eq!(a.gq_stream, b.gq_stream);
+        assert_eq!(a.gq_seg_ofs, b.gq_seg_ofs);
+        assert_eq!(a.n_counter, b.n_counter);
+    }
+    for s in &blob.sections {
+        assert_eq!(
+            blob.section_data_named(&raw, s.kind, &s.name),
+            after.section_data_named(&output, s.kind, &s.name)
+        );
+    }
+    assert_eq!(blob.tensors.len(), after.tensors.len());
+    for (a, b) in blob.tensors.iter().zip(&after.tensors) {
+        assert_eq!(a.name, b.name);
+        assert_eq!(a.bytes, b.bytes);
+        assert_eq!(
+            a.init.clone().map(|r| blob.init[r].to_vec()),
+            b.init.clone().map(|r| after.init[r].to_vec())
+        );
+    }
+    let a = plowrt::memory::vmm::LiveKvLayout::from_blob(&blob)?;
+    let b = plowrt::memory::vmm::LiveKvLayout::from_blob(&after)?;
+    assert_eq!(format!("{:?}", a.geometry), format!("{:?}", b.geometry));
+    assert_eq!(a.full_tensors, b.full_tensors);
+    assert_eq!(a.ring_tensors, b.ring_tensors);
+    assert_eq!(a.cache_tensors, b.cache_tensors);
+    std::fs::write(&args[2], output)?;
+    std::fs::write(
+        Path::new(&args[2]).with_extension("binding-proof.json"),
+        serde_json::to_vec_pretty(
+            &serde_json::json!({"all_program_tables_exact":true,"all_tensors_and_existing_sections_exact":true,"live_kv_layout_exact":true,"decode_objects":metadata}),
+        )?,
+    )?;
+    println!(
+        "PASS compiler-owned bindings; all existing instructions/counters/tensors/KV unchanged"
+    );
+    Ok(())
+}
